def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    color = next(v for v in counts if v != bg)
    out = [row[:] for row in grid]
    row_marks = {r: [c for c, v in enumerate(grid[r]) if v == color] for r in range(h)}
    col_marks = {c: [r for r in range(h) if grid[r][c] == color] for c in range(w)}

    # Dense rows are horizontal strokes. A two-point row is a stroke only
    # when its points are not both part of vertical strokes.
    hrows = {r for r, cs in row_marks.items() if len(cs) >= 3}
    vcols = {c for c, rs in col_marks.items()
             if len(rs) >= 2 and any(r not in hrows for r in rs)}
    for r, cs in row_marks.items():
        if len(cs) == 2 and not (cs[0] in vcols and cs[1] in vcols):
            hrows.add(r)

    # Keep only columns with a marker outside the final horizontal strokes.
    vcols = {c for c, rs in col_marks.items()
             if len(rs) >= 2 and any(r not in hrows for r in rs)}
    hs = {r: [min(row_marks[r]), max(row_marks[r])] for r in hrows}
    vs = {c: [min(col_marks[c]), max(col_marks[c])] for c in vcols}

    # Join each stroke to the nearest perpendicular stroke beyond its ends.
    for r, span in hs.items():
        left = [c for c in vcols if c < span[0]]
        right = [c for c in vcols if c > span[1]]
        if left: span[0] = max(left)
        if right: span[1] = min(right)
    for c, span in vs.items():
        above = [r for r, (lo, hi) in hs.items() if r < span[0] and lo <= c <= hi]
        below = [r for r, (lo, hi) in hs.items() if r > span[1] and lo <= c <= hi]
        if above: span[0] = max(above)
        if below: span[1] = min(below)

    for r, (lo, hi) in hs.items():
        for c in range(lo, hi + 1):
            if grid[r][c] == bg: out[r][c] = 2
    for c, (lo, hi) in vs.items():
        for r in range(lo, hi + 1):
            if grid[r][c] == bg: out[r][c] = 2
    return out

